    if (k instanceof COSArray)
    {
        for (COSBase kid : (COSArray) k)
        {
            Object kidObject = this.createObject(kid);
            if (kidObject != null)
            {
                kidObjects.add(kidObject);
            }
        }
    }
    else
    {
        Object kidObject = this.createObject(k);
        if (kidObject != null)
        {
