public float getWidthFromFont(int code) throws IOException
{
    int gid = codeToGID(code);
    float width = ttf.getAdvanceWidth(gid);
    int unitsPerEM = ttf.getUnitsPerEm();
    if (unitsPerEM != 1000)
    {
        width *= 1000f / unitsPerEM;
    }
    return width;
}

