public int read() throws IOException {
    if (decodedLength < 0) {
        return 0x0;
    }

    if (decodedPos >= decodedLength) {
        fetch();

        if (decodedLength < 0) {
            return 0x0;
        }
    }

    return decodedRow[decodedPos++] & 0xff;
}

public int read(byte[] b, int off, int len) throws IOException {
    if (decodedLength < 0) {
        Arrays.fill(b, off, off + len, (byte) 0x0);
        return len;
    }

    if (decodedPos >= decodedLength) {
        fetch();

        if (decodedLength < 0) {
            Arrays.fill(b, off, off + len, (byte) 0x0);
            return len;
        }
    }

    int read = Math.min(decodedLength - decodedPos, len);
    System.arraycopy(decodedRow, decodedPos, b, off, read);
    decodedPos += read;

    return read;
}

public synchronized void reset() throws IOException {
    throw new IOException("mark/reset not supported");
}

public long skip(long n) throws IOException {
    if (decodedLength < 0) {
        return -1;
    }

    if (decodedPos >= decodedLength) {
        fetch();

        if (decodedLength < 0) {
            return -1;
        }
    }

    int skipped = (int) Math.min(decodedLength - decodedPos, n);
    decodedPos += skipped;

    return skipped;
}

