public PDExtendedGraphicsState getExtGState(COSName name)
{
    COSObject indirect = getIndirect(COSName.EXT_G_STATE, name);
    if (cache != null && indirect != null)
    {
        PDExtendedGraphicsState cached = cache.getExtGState(indirect);
        if (cached != null)
        {
            return cached;
        }
    }

    // get the instance
    PDExtendedGraphicsState extGState = null;
    COSBase base = get(COSName.EXT_G_STATE, name);
    if (base instanceof COSDictionary)
    {
        extGState = new PDExtendedGraphicsState((COSDictionary) base);
    }

    if (cache != null && indirect != null)
    {
        cache.put(indirect, extGState);
    }
    return extGState;
}

public void drawPage(Graphics2D g, PDRectangle pageSize) throws IOException
{
    graphics = g;
    xform = graphics.getTransform();
    Matrix m = new Matrix(xform);
    xformScalingFactorX = Math.abs(m.getScalingFactorX());
    xformScalingFactorY = Math.abs(m.getScalingFactorY());
    initialClip = graphics.getClip();
    this.pageSize = pageSize;

    setRenderingHints();

    graphics.translate(0, pageSize.getHeight());
    graphics.scale(1, -1);

    // adjust for non-(0,0) crop box
    graphics.translate(-pageSize.getLowerLeftX(), -pageSize.getLowerLeftY());

    processPage(getPage());

    for (PDAnnotation annotation : getPage().getAnnotations(annotationFilter))
    {
        showAnnotation(annotation);
    }

    graphics = null;
}

