public String getTag(Map<Integer, Integer> gidToCid)
{
    // deterministic
    long num = gidToCid.hashCode();

    // base25 encode
    StringBuilder sb = new StringBuilder();
    do
    {
        long div = num / 25;
        int mod = (int)(num % 25);
        sb.append(BASE25.charAt(mod));
        num = div;
    } while (num != 0 && sb.length() < 6);

    // pad
    while (sb.length() < 6)
    {
        sb.insert(0, 'A');
    }

    sb.append('+');
    return sb.toString();
}

