public boolean equals(Object obj)
{
    if (!(obj instanceof SmallMap.SmallMapEntry))
    {
        return false;
    }
    @SuppressWarnings("unchecked")
    SmallMapEntry other = (SmallMapEntry) obj;

    return getKey().equals(other.getKey()) && getValue().equals(other.getValue());
}

